<# SessionStart-Hook fuer Windows. In settings.json per powershell -NoProfile -File aufrufen. #>
[CmdletBinding()] param()
$betrieb = Join-Path $env:USERPROFILE 'maschinenraum\betrieb'; $merker = Join-Path $betrieb '.sitzungsstart-gesehen'; New-Item -ItemType Directory -Force $betrieb | Out-Null; New-Item -ItemType File -Force $merker | Out-Null; $anzeige = Join-Path $betrieb 'laufanzeige.md'; $alt = @{}; Get-Content $merker | ForEach-Object { $p=$_.Split("`t",2); if($p.Count -eq 2){$alt[$p[0]]=[int]$p[1]} }; $neu=@(); if(Test-Path $anzeige){$zeilen=@(Get-Content $anzeige); $von=if($alt.ContainsKey($anzeige)){$alt[$anzeige]}else{0}; if($zeilen.Count -gt $von){$fehler=$zeilen[$von..($zeilen.Count-1)]|Where-Object{$_ -like '*| FEHLER |*'}|Select-Object -Last 10; if($fehler){Write-Output "Neue FEHLER in $anzeige seit der letzten Sitzung:"; $fehler}}; $neu += "$anzeige`t$($zeilen.Count)"}; $neu | Set-Content $merker
